-- Tokyo Night colours from tools/color.nix, generated by theme_home.nix.
-- Falls back to a few literal values so a missing file doesn't break the config.
local ok, colors = pcall(dofile, os.getenv("HOME") .. "/.config/theme/colors.lua")
if not ok then
    colors = { bg = "1a1b26", fg = "c0caf5", blue = "7aa2f7", magenta = "bb9af7", comment = "565f89" }
end

-- rgba("7aa2f7", "ee") -> "rgba(7aa2f7ee)"
function colors.rgba(name, alpha)
    return "rgba(" .. colors[name] .. (alpha or "ff") .. ")"
end

return colors
